CREATE TABLE IF NOT EXISTS deployment_identity (id integer PRIMARY KEY CHECK (id = 1), environment text NOT NULL CHECK (environment IN ('development','production')));
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, is_admin boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS businesses (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id uuid NOT NULL REFERENCES users(id), business_id uuid NOT NULL REFERENCES businesses(id), role text NOT NULL CHECK (role IN ('owner','staff')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(user_id,business_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_staff_business ON memberships(user_id) WHERE role = 'staff';
CREATE TABLE IF NOT EXISTS items (id uuid NOT NULL, business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, canonical_unit text NOT NULL, version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,id));
CREATE TABLE IF NOT EXISTS item_units (id uuid NOT NULL, business_id uuid NOT NULL, item_id uuid NOT NULL, label text NOT NULL, factor numeric(18,6) NOT NULL CHECK (factor > 0), price_minor bigint NOT NULL CHECK (price_minor >= 0), active boolean NOT NULL DEFAULT true, PRIMARY KEY(business_id,id), FOREIGN KEY(business_id,item_id) REFERENCES items(business_id,id));
CREATE TABLE IF NOT EXISTS catalogue_revisions (business_id uuid NOT NULL, item_id uuid NOT NULL, version integer NOT NULL, snapshot jsonb NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,item_id,version));
CREATE TABLE IF NOT EXISTS change_log (cursor bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, business_id uuid NOT NULL REFERENCES businesses(id), kind text NOT NULL, entity_id uuid NOT NULL, version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS change_log_business_cursor ON change_log(business_id,cursor);
CREATE TABLE IF NOT EXISTS operations (business_id uuid NOT NULL, operation_id uuid NOT NULL, operation_type text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), payload_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,operation_id));
CREATE TABLE IF NOT EXISTS audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, business_id uuid, actor_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, entity_id uuid, operation_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_limits (key_hash text PRIMARY KEY, failures integer NOT NULL DEFAULT 0, locked_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
